head.b:skin:
/* ----- VARIABLES ----- */
:root {
  --primary-hue: 210;
  --primary: hsl(var(--primary-hue), 89%, 60%);
  --bg: #f5f5f5;
  --text: #333;
  --muted: #666;
  --card: #fff;
  --border: #ddd;
  --radius: 12px;
  --shadow: 0 4px 12px rgba(0,0,0,.1);
  --max: 1140px;
}

/* ----- BASE STYLES ----- */
body {
  margin: 0;
  font-family: 'Poppins', system-ui, Segoe UI, Roboto, sans-serif;
  font-size: 16px;
  line-height: 1.7;
  color: var(--text);
  background: var(--bg);
  transition: background .3s, color .3s;
}

a {
  text-decoration: none;
  color: var(--primary);
  transition: all .3s ease;
}

a:hover {
  opacity: .8;
}

img {
  max-width: 100%;
  height: auto;
  border-radius: var(--radius);
}

.container {
  max-width: var(--max);
  margin: auto;
  padding: 0 20px;
}

.section {
  padding: 80px 0;
}

.title {
  text-align: center;
  font-size: 36px;
  font-weight: 600;
  margin: 0 0 40px 0;
}

.btn {
  display: inline-block;
  padding: 12px 24px;
  border-radius: 50px;
  border: 2px solid var(--primary);
  color: var(--primary);
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: .5px;
  transition: all .3s;
}

.btn.filled {
  background: var(--primary);
  color: #fff;
}

.btn:hover {
  transform: translateY(-3px);
  box-shadow: 0 4px 8px rgba(0,0,0,.1);
}

/* ----- HEADER ----- */
header {
  position: sticky;
  top: 0;
  background: rgba(255,255,255,.8);
  backdrop-filter: blur(10px);
  border-bottom: 1px solid var(--border);
  z-index: 100;
  padding: 10px 0;
}

nav {
  display: flex;
  gap: 24px;
  justify-content: flex-end;
  flex-wrap: wrap;
}

nav a {
  padding: 8px 12px;
  border-radius: 8px;
  font-weight: 500;
}

nav a:hover, nav a.active {
  background: hsla(var(--primary-hue), 89%, 60%, .1);
}

.toggle-theme {
  cursor: pointer;
  padding: 6px 10px;
  border-radius: 8px;
  border: 1px solid var(--border);
  background: var(--card);
  font-size: 18px;
}

/* ----- SECTIONS ----- */
.home {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 40px;
  min-height: 80vh;
}

.home-info {
  flex: 1.5;
}

.home-img {
  flex: 1;
  text-align: center;
}

.home h1 {
  font-size: 36px;
  font-weight: 700;
  margin-bottom: 16px;
}

.home {
  flex-direction: column;
  text-align: center;
}
.home-info {
  order: 2;
}
.home-img {
  order: 1;
}

.about-content, .contact-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: 30px;
  align-items: center;
}

.card {
  background: var(--card);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 24px;
  box-shadow: var(--shadow);
  transition: all .3s;
}

.card:hover {
  transform: translateY(-5px);
  box-shadow: 0 8px 16px rgba(0,0,0,.1);
}

.services-grid, .portfolio-grid, .blog-posts {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
  gap: 30px;
}

/* ----- FOOTER ----- */
footer {
  padding: 40px 0;
  text-align: center;
  color: var(--muted);
  border-top: 1px solid var(--border);
}

/* ----- RESPONSIVE ----- */
@media(min-width: 768px) {
  .home {
    flex-direction: row;
    text-align: left;
  }
  .home-info {
    order: 1;
  }
  .home-img {
    order: 2;
  }
  .home h1 {
    font-size: 48px;
  }
  .about-content, .contact-grid {
    grid-template-columns: 1fr 1fr;
  }
}

/* ----- DARK MODE ----- */
body.dark {
  --bg: #1a1a1a;
  --text: #eee;
  --card: #2c2c2c;
  --border: #444;
}

body.dark header {
  background: rgba(44,44,44,.8);
}

/* ----- COLOR SWITCHER ----- */
.color-switcher {
  display: flex;
  gap: 8px;
  justify-content: center;
  margin: 20px 0;
}

.color-dot {
  width: 24px;
  height: 24px;
  border-radius: 50%;
  cursor: pointer;
  border: 2px solid var(--card);
  box-shadow: 0 0 0 1px var(--border);
  transition: all .3s;
}

.color-dot:hover {
  transform: scale(1.1);
}

/* ----- BLOG ----- */
.blog-posts .card {
  margin-bottom: 20px;
}
.post-title a {
  color: var(--text);
}
.post-header {
  color: var(--muted);
  font-size: 14px;
  margin-bottom: 16px;
}
.post-body {
  line-height: 1.8;
}
.post-body blockquote {
  border-left: 3px solid var(--primary);
  padding-left: 16px;
  margin-left: 0;
  font-style: italic;
}

.search-form {
  display: flex;
  border: 1px solid var(--border);
  border-radius: 50px;
  overflow: hidden;
}

.search-form input {
  border: none;
  padding: 8px 16px;
  background: transparent;
  outline: none;
}

.search-form button {
  border: none;
  background: var(--primary);
  color: #fff;
  padding: 8px 12px;
  cursor: pointer;
}

.blog-pager {
  display: flex;
  justify-content: space-between;
  margin-top: 30px;
}

.blog-pager a {
  padding: 10px 16px;
  border-radius: 8px;
  border: 1px solid var(--border);
  background: var(--card);
}
